using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;
public static class SetupBikeRack {
 static void Configure(BicycleController b){b.cargoSlots[0].name="Rear rack box front";b.cargoSlots[0].localPosition=new Vector3(0,.49f,-.48f);b.cargoSlots[1].name="Rear rack box back";b.cargoSlots[1].localPosition=new Vector3(0,.49f,-.74f);if(!b.exclusiveBagSlot){var a=new GameObject("Rear rack single bag").transform;a.SetParent(b.transform,false);b.exclusiveBagSlot=a;}b.exclusiveBagSlot.localPosition=new Vector3(0,.60f,-.62f);EditorUtility.SetDirty(b);}
 public static string Main(){const string path="Assets/Models/bicycle/Optimized/Bicycle_Rideable.prefab";var root=PrefabUtility.LoadPrefabContents(path);try{Configure(root.GetComponent<BicycleController>());PrefabUtility.SaveAsPrefabAsset(root,path);}finally{PrefabUtility.UnloadPrefabContents(root);}var b=Object.FindObjectsByType<BicycleController>(FindObjectsSortMode.None).First(b=>!b.motorDriven);Configure(b);PrefabUtility.RecordPrefabInstancePropertyModifications(b);foreach(var slot in b.cargoSlots)PrefabUtility.RecordPrefabInstancePropertyModifications(slot);EditorSceneManager.MarkSceneDirty(b.gameObject.scene);EditorSceneManager.SaveScene(b.gameObject.scene);return "Bicycle prefab and scene rack: one bag OR two boxes, all centered over the existing rear rack.";}}
